// FUNCTION: BFME2 0x0053B387 size=144 name=?update@AnimateWindowManager@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void AnimateWindowManager::update()
{
	ProcessAnimateWindow *processAnim;
	if (m_needsUpdate)
	{
		AnimateWindowList::iterator it = m_winMustFinishList.begin();
		m_needsUpdate = false;
		// Keep updating while any window that must finish is still moving.
		for (; it != m_winMustFinishList.end(); ++it)
		{
			AnimateWindow *animWin = *it;
			if (!animWin)
				return;
			processAnim = getProcessAnimate((AnimTypes)animWin->m_animType);
			if (processAnim)
			{
				Bool done;
				if (m_reverse)
					done = processAnim->reverseAnimateWindow(animWin);
				else
					done = processAnim->updateAnimateWindow(animWin);
				if (!done)
					m_needsUpdate = true;
			}
		}
	}
	for (AnimateWindowList::iterator it = m_winList.begin(); it != m_winList.end(); ++it)
	{
		AnimateWindow *animWin = *it;
		if (!animWin)
			return;
		processAnim = getProcessAnimate((AnimTypes)animWin->m_animType);
		if (m_reverse)
		{
			if (processAnim)
				processAnim->reverseAnimateWindow(animWin);
		}
		else
		{
			if (processAnim)
				processAnim->updateAnimateWindow(animWin);
		}
	}
}

// FUNCTION: BFME2 0x0053B417 size=160 name=?reverseAnimateWindow@AnimateWindowManager@@QAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void AnimateWindowManager::reverseAnimateWindow()
{
	unsigned int maxDelay = 0;
	m_reverse = true;
	m_needsUpdate = true;
	// The longest delay of the windows that must finish starts every reversal.
	AnimateWindowList::iterator it;
	for (it = m_winMustFinishList.begin(); it != m_winMustFinishList.end(); ++it)
	{
		AnimateWindow *animWin = *it;
		if (!animWin)
			return;
		if (animWin->getDelay() > maxDelay)
			maxDelay = animWin->getDelay();
	}
	for (it = m_winMustFinishList.begin(); it != m_winMustFinishList.end(); ++it)
	{
		AnimateWindow *animWin = *it;
		if (!animWin)
			return;
		ProcessAnimateWindow *processAnim = getProcessAnimate((AnimTypes)animWin->m_animType);
		if (processAnim)
			processAnim->initReverseAnimateWindow(animWin, maxDelay);
		animWin->setFinished(false);
	}
	for (it = m_winList.begin(); it != m_winList.end(); ++it)
	{
		AnimateWindow *animWin = *it;
		if (!animWin)
			return;
		ProcessAnimateWindow *processAnim = getProcessAnimate((AnimTypes)animWin->m_animType);
		if (processAnim)
			processAnim->initReverseAnimateWindow(animWin);
		animWin->setFinished(false);
	}
}

// FUNCTION: BFME2 0x0053B4B7 size=105 name=?resetToRestPosition@AnimateWindowManager@@QAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void AnimateWindowManager::resetToRestPosition()
{
	m_reverse = true;
	m_needsUpdate = true;
	AnimateWindowList::iterator it;
	for (it = m_winMustFinishList.begin(); it != m_winMustFinishList.end(); ++it)
	{
		AnimateWindow *animWin = *it;
		if (!animWin)
			return;
		ICoord2D restPos = animWin->m_restPos;
		GameWindow *win = animWin->getGameWindow();
		if (win)
			win->winSetPosition(restPos.x, restPos.y);
	}
	for (it = m_winList.begin(); it != m_winList.end(); ++it)
	{
		AnimateWindow *animWin = *it;
		if (!animWin)
			return;
		ICoord2D restPos = animWin->m_restPos;
		GameWindow *win = animWin->getGameWindow();
		if (win)
			win->winSetPosition(restPos.x, restPos.y);
	}
}

// 0x0053B520: deletes every record in a window list (its callers pass the list in edi).
static void clearWinList(AnimateWindowManager::AnimateWindowList &winList)
{
	while (!winList.empty())
	{
		AnimateWindow *animWin = winList.front();
		winList.pop_front();
		if (animWin)
			::delete animWin;
	}
}

// FUNCTION: BFME2 0x0053B550 size=400 name=??0AnimateWindowManager@@QAE@XZ evidence=N:ledger tier=B hypothesis:cohesion
AnimateWindowManager::AnimateWindowManager()
{
	// One process object per animation style.
	m_slideFromRight = new ProcessAnimateWindowSlideFromRight;
	m_slideFromRightFast = new ProcessAnimateWindowSlideFromRightFast;
	m_slideFromLeft = new ProcessAnimateWindowSlideFromLeft;
	m_slideFromTop = new ProcessAnimateWindowSlideFromTop;
	m_slideFromTopFast = new ProcessAnimateWindowSlideFromTopFast;
	m_slideFromBottom = new ProcessAnimateWindowSlideFromBottom;
	m_spiral = new ProcessAnimateWindowSpiral;
	m_slideFromBottomTimed = new ProcessAnimateWindowSlideFromBottomTimed;
	m_winList.clear();
	m_needsUpdate = false;
	m_reverse = false;
	m_winMustFinishList.clear();
}

// FUNCTION: BFME2 0x0053B6E0 size=260 name=??1AnimateWindowManager@@UAE@XZ evidence=N:ledger tier=B hypothesis:cohesion
AnimateWindowManager::~AnimateWindowManager()
{
	if (m_slideFromRight)
		::delete m_slideFromRight;
	if (m_slideFromRightFast)
		::delete m_slideFromRightFast;
	if (m_slideFromLeft)
		::delete m_slideFromLeft;
	if (m_slideFromTop)
		::delete m_slideFromTop;
	if (m_slideFromTopFast)
		::delete m_slideFromTopFast;
	if (m_slideFromBottom)
		::delete m_slideFromBottom;
	if (m_spiral)
		::delete m_spiral;
	if (m_slideFromBottomTimed)
		::delete m_slideFromBottomTimed;
	m_slideFromRight = NULL;
	resetToRestPosition();
	clearWinList(m_winList);
	clearWinList(m_winMustFinishList);
}

// FUNCTION: BFME2 0x0053B7E4 size=31 name=?init@AnimateWindowManager@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void AnimateWindowManager::init()
{
	clearWinList(m_winList);
	clearWinList(m_winMustFinishList);
	m_needsUpdate = false;
	m_reverse = false;
}

// FUNCTION: BFME2 0x0053B803 size=36 name=?reset@AnimateWindowManager@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void AnimateWindowManager::reset()
{
	resetToRestPosition();
	clearWinList(m_winList);
	clearWinList(m_winMustFinishList);
	m_needsUpdate = false;
	m_reverse = false;
}

// FUNCTION: BFME2 0x0053B843 size=155 name=?registerGameWindow@AnimateWindowManager@@QAEXPAVGameWindow@@W4AnimTypes@@_NII@Z evidence=N:ledger tier=B hypothesis:K
void AnimateWindowManager::registerGameWindow(GameWindow *win, AnimTypes animType, bool needsToFinish,
	unsigned int millisecondsToFinish, unsigned int delayMs)
{
	if (!win)
		return;
	if (animType <= 0 || animType >= 9)
		return;

	AnimateWindow *animWin = new AnimateWindow;
	animWin->m_win = win;
	animWin->m_animType = animType;
	animWin->m_needsToFinish = needsToFinish;
	animWin->m_delay = delayMs;

	ProcessAnimateWindow *processAnim = getProcessAnimate(animType);
	if (processAnim)
	{
		processAnim->setMaxDuration(millisecondsToFinish);
		processAnim->initAnimateWindow(animWin);
	}

	if (needsToFinish)
	{
		m_winMustFinishList.push_back(animWin);
		m_needsUpdate = true;
	}
	else
	{
		m_winList.push_back(animWin);
	}
}

